package com.example.investsmart.settlement;
import com.example.investsmart.dto.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
class GroupedJournalChangeIntegrationTests {
    PeriodChargeAdapterTests fixture;
    @BeforeEach void setup(){fixture=new PeriodChargeAdapterTests();fixture.setup();}
    @AfterEach void close(){fixture.close();}
    BigDecimal change(JournalPeriodEvidence p,int bucket){return p.selectedGroupedChanges().buckets().get(bucket).change();}
    @Test void ownedChargeCountsOnceWhileDirectScopeAndForeignHistoryStayUnavailable(){var before=fixture.writer.balances();var p=fixture.read();assertEquals(new BigDecimal("-20.00"),change(p,0));assertEquals(new BigDecimal("0.00"),change(p,1));assertTrue(p.selectedDirectChanges().buckets().stream().allMatch(b->b.change()==null));assertFalse(p.selectedGroupedChanges().fullAccountSummaryAvailable());assertEquals(before,fixture.writer.balances());var other=fixture.service.read(fixture.f.other.getEmail(),p.fromInclusive(),p.toExclusive());assertNull(change(other,0));assertTrue(other.entries().isEmpty());}
    @Test void partialAndCorruptedSourcesKeepRawEvidenceButWithholdGroupedChanges(){fixture.f.db.update("UPDATE settlement_journal SET occurred_at=? WHERE reference_kind='CHARGE'",java.sql.Timestamp.from(SettlementFundsTests.BEFORE.plusSeconds(1)));var partial=fixture.read();assertNull(change(partial,0));assertEquals(1,partial.chargeGrouping().sourceEvidence().size());fixture.f.db.update("UPDATE settlement_journal SET occurred_at=? WHERE reference_kind='CHARGE'",java.sql.Timestamp.from(SettlementFundsTests.BEFORE));fixture.f.db.update("UPDATE settlement_allocation_events SET amount=amount+1 WHERE action='SPEND'");var broken=fixture.read();assertFalse(broken.entries().isEmpty());assertNull(change(broken,0));assertNull(change(broken,1));}
    @Test void emptyZeroAndCacheInvalidationRemainExplicit(){var p=fixture.read();assertNull(p.withAssessment(p.assessment()).selectedGroupedChanges());assertNull(p.withSummaryEligibility(p.summaryEligibility()).selectedGroupedChanges());var replaced=p.withChargeGrouping(p.chargeGrouping());assertNull(replaced.assessment());assertNull(replaced.selectedDirectChanges());assertNull(replaced.selectedGroupedChanges());fixture.f.db.update("DELETE FROM settlement_journal WHERE user_id=1");var empty=fixture.read();assertEquals(new BigDecimal("0.00"),change(empty,0));assertFalse(empty.completeFinancialHistory());}
    @Test void groupedCalculationRunsInsideExistingIndependentReadOnlySnapshot(){var f=fixture.f;var source=f.context.getBean(javax.sql.DataSource.class);Object[] resource={null};doAnswer(call->{resource[0]=TransactionSynchronizationManager.getResource(source);return call.callRealMethod();}).when(f.periodRepository).entries(eq(1L),any(),any());doAnswer(call->{assertSame(resource[0],TransactionSynchronizationManager.getResource(source));assertTrue(TransactionSynchronizationManager.isCurrentTransactionReadOnly());assertEquals(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ,TransactionSynchronizationManager.getCurrentTransactionIsolationLevel());var p=(JournalPeriodEvidence)call.getArgument(0);assertNotNull(p.selectedDirectChanges());assertNull(p.selectedGroupedChanges());return call.callRealMethod();}).when(f.groupedSummarizer).summarize(any());f.write.execute(status->{var outer=TransactionSynchronizationManager.getResource(source);fixture.read();assertNotSame(outer,resource[0]);assertSame(outer,TransactionSynchronizationManager.getResource(source));return null;});verify(f.groupedSummarizer,times(1)).summarize(any());verify(f.repository,times(1)).coverage(1);verify(f.periodRepository,times(1)).entries(eq(1L),any(),any());verify(f.periodChargeRepository,times(1)).children(eq(1L),anyList(),anyInt());verify(f.fundingRepository,times(2)).evidence(eq(1L),anyList(),anyInt());verifyNoInteractions(f.chargeRepository);}
}
